// Low-level output of a 16-bit word
// Requires ioperm(2) or iopl(2) access (or root)

const unsigned short CMD_VALUE = 0xCDCD;
const unsigned short REG_PORT  = 0x2A0; // Example I/O Port Address

// Write CMD_VALUE (16 bits) to REG_PORT
outw(CMD_VALUE, REG_PORT);

